"""Local, deterministic editing. All paths are generated by the server."""
from __future__ import annotations
import json
import math
import os
import re
import subprocess
from pathlib import Path
from PIL import Image, ImageOps, ImageDraw, ImageFont

class MediaError(ValueError):
    pass

def run(args, timeout=180):
    result = subprocess.run([str(a) for a in args], capture_output=True, text=True, encoding="utf-8", errors="replace", timeout=timeout)
    if result.returncode:
        # Commands only contain local paths. Keep diagnostics local and bounded.
        raise MediaError(result.stderr[-1600:] or 'Media processing failed.')
    return result.stdout

def probe(path: Path):
    info = json.loads(run(['ffprobe', '-v', 'error', '-show_format', '-show_streams', '-of', 'json', path], 30))
    streams = info.get('streams', [])
    video = next((s for s in streams if s['codec_type'] == 'video' and not s.get('disposition', {}).get('attached_pic')), None)
    duration = float(info.get('format', {}).get('duration', 0))
    return {'duration': duration, 'width': video['width'] if video else 0,
            'height': video['height'] if video else 0, 'has_audio': any(s['codec_type'] == 'audio' for s in streams),
            'has_video': bool(video)}

def ffmpeg(args, timeout=180):
    return run(['ffmpeg', '-hide_banner', '-loglevel', 'error', '-nostdin', '-y', '-threads', '2', *args], timeout)

def clean_image(src: Path, dst: Path):
    try:
        with Image.open(src) as image:
            if image.width * image.height > 40_000_000:
                raise MediaError('Image exceeds 40 megapixels.')
            image = ImageOps.exif_transpose(image).convert('RGB')
            image.thumbnail((2048, 2048))
            image.save(dst, quality=94)
    except (OSError, Image.DecompressionBombError) as exc:
        raise MediaError('Please upload a supported image.') from exc

def board(paths: list[Path], dst: Path):
    result = Image.new('RGB', (768 * len(paths), 768), '#f0f0f0')
    for i, path in enumerate(paths):
        with Image.open(path) as image:
            tile = ImageOps.contain(image.convert('RGB'), (728, 728))
            result.paste(tile, (i * 768 + (768-tile.width)//2, (768-tile.height)//2))
    result.save(dst, quality=93)

def detect_cuts(src: Path, duration: float):
    result = subprocess.run(['ffmpeg', '-hide_banner', '-nostdin', '-i', str(src), '-an',
        '-vf', "scale=240:-2,select='gt(scene,0.30)',showinfo", '-f', 'null', '-'], capture_output=True, text=True, encoding="utf-8", errors="replace", timeout=180)
    if result.returncode:
        raise MediaError('Scene detection failed. Check the reference video encoding.')
    raw = [float(s) for s in re.findall(r'pts_time:([0-9.]+)', result.stderr)]
    cuts = [0.0]
    for t in raw:
        if t - cuts[-1] >= .5 and duration - t >= .5:
            cuts.append(round(t, 3))
    cuts.append(duration)
    # Keep source edits, split long uninterrupted takes for controllable generations.
    expanded = [0.0]
    for a, b in zip(cuts, cuts[1:]):
        count = max(1, math.ceil((b-a)/8))
        expanded.extend(round(a + (b-a)*n/count, 3) for n in range(1, count+1))
    return expanded

def extract_shot(src: Path, directory: Path, start: float, end: float):
    directory.mkdir(parents=True, exist_ok=True)
    duration = end-start
    # Portrait and landscape retain their original composition; never center crop.
    ffmpeg(['-ss', start, '-i', src, '-t', duration, '-vf', 'scale=1280:1280:force_original_aspect_ratio=decrease:force_divisible_by=2,setsar=1',
        '-c:v', 'libx264', '-preset', 'fast', '-crf', '19', '-c:a', 'aac', '-b:a', '160k', '-movflags', '+faststart', directory/'source.mp4'])
    for name, fraction in [('first', .03), ('middle', .5), ('last', .94)]:
        ffmpeg(['-ss', max(0, duration*fraction), '-i', directory/'source.mp4', '-frames:v', '1', '-vf', 'scale=960:960:force_original_aspect_ratio=decrease', directory/f'{name}.jpg'])
    if probe(directory/'source.mp4')['has_audio']:
        ffmpeg(['-i', directory/'source.mp4', '-vn', '-ac', '1', '-ar', '44100', directory/'source.wav'])
    # Pad short motion references to 3s for provider compatibility; trim on assembly.
    ffmpeg(['-i', directory/'source.mp4', '-vf', f'tpad=stop_mode=clone:stop_duration={max(0,3-duration)+.05}',
        '-t', max(3, duration), '-an', '-c:v', 'libx264', '-preset', 'fast', '-crf', '19', '-movflags', '+faststart', directory/'driving.mp4'])

def fit_voice(src: Path, dst: Path, duration: float):
    info = probe(src)
    if not info['has_audio'] or info['duration'] <= 0:
        raise MediaError('The provider did not return readable audio.')
    speed = max(1.0, info['duration']/duration)
    if speed > 1.25:
        raise MediaError(f'Speech is {info["duration"]:.1f}s for a {duration:.1f}s shot. Shorten the script or upload a shorter voice take; it will not be truncated.')
    ffmpeg(['-i', src, '-vn', '-af', f'atempo={speed:.6f},apad', '-t', duration, '-ar', '48000', '-ac', '2', dst])
    return {'source_duration': info['duration'], 'speed': round(speed, 3)}

def normalize_clip(src: Path, dst: Path, duration: float, size: tuple[int, int], audio: Path | None, keep_audio=False):
    info = probe(src)
    if not info['has_video'] or info['duration'] < .1:
        raise MediaError('The provider did not return a readable video.')
    # Preserve motion speed; pad a small deficit only, never silently stretch or repeat a short failed generation.
    if info['duration'] + .25 < duration:
        raise MediaError(f'Generated clip ({info["duration"]:.2f}s) is shorter than the shot ({duration:.2f}s). Retry this shot.')
    w, h = size
    args = ['-i', src]
    if audio:
        args += ['-i', audio]
    elif not (keep_audio and info['has_audio']):
        args += ['-f', 'lavfi', '-i', 'anullsrc=r=48000:cl=stereo']
    args += ['-map', '0:v:0', '-map', '1:a:0' if audio or not (keep_audio and info['has_audio']) else '0:a:0',
        '-vf', f'scale={w}:{h}:force_original_aspect_ratio=decrease,pad={w}:{h}:(ow-iw)/2:(oh-ih)/2,setsar=1,fps=30,tpad=stop_mode=clone:stop_duration=0.25',
        '-af', 'apad', '-t', duration, '-c:v', 'libx264', '-preset', 'fast', '-crf', '18', '-c:a', 'aac', '-ar', '48000', '-ac', '2', '-movflags', '+faststart', dst]
    ffmpeg(args)

def concat_path(path: Path):
    # FFmpeg's concat file has its own quoting syntax, independent of cmd.exe.
    # Forward slashes also work with Windows drive paths; preserve apostrophes.
    value=path.resolve().as_posix().replace("'", "'\\''")
    return "'"+value+"'"

def assemble(paths: list[Path], dst: Path, music: Path | None = None, durations: list[float] | None = None):
    concat = dst.parent / 'concat.txt'
    # Paths are generated UUIDs, not user filenames.
    durations=durations or [probe(path)['duration'] for path in paths]
    concat.write_text(''.join(f"file {concat_path(path)}\nduration {duration:.9f}\n" for path,duration in zip(paths,durations)), encoding='utf-8')
    intermediate = dst.parent / 'assembled.mp4'
    ffmpeg(['-f', 'concat', '-safe', '0', '-i', concat, '-vf', 'fps=30', '-af', 'aresample=async=1:first_pts=0', '-t',sum(durations),
        '-c:v','libx264','-preset','fast','-crf','18','-c:a','aac','-ar','48000','-movflags','+faststart',intermediate])
    if music:
        ffmpeg(['-i', intermediate, '-stream_loop', '-1', '-i', music,
            '-filter_complex', '[1:a]volume=0.12[m];[0:a][m]amix=inputs=2:duration=first:normalize=0[a]',
            '-map', '0:v', '-map', '[a]', '-c:v', 'copy', '-c:a', 'aac', '-movflags', '+faststart', dst])
    else:
        intermediate.replace(dst)

def add_brand(src: Path, dst: Path, product: Path | None, cta: str, seconds: float):
    info = probe(src)
    w,h = info['width'],info['height']
    overlay = Image.new('RGBA', (w,h), (0,0,0,0))
    draw = ImageDraw.Draw(overlay)
    font_size=max(16,int(w*.035))
    candidates=[Path(os.environ.get('WINDIR','C:/Windows'))/'Fonts'/'segoeui.ttf',
                Path(os.environ.get('WINDIR','C:/Windows'))/'Fonts'/'arial.ttf',
                Path('/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf')]
    font=None
    for path in candidates:
        try:
            font=ImageFont.truetype(str(path),font_size)
            break
        except OSError:continue
    if font is None:font=ImageFont.load_default(size=font_size)
    draw.rectangle((0,int(h*.79),w,h),fill=(6,9,8,225))
    if product:
        with Image.open(product) as image:
            image=ImageOps.contain(image.convert('RGBA'),(int(w*.2),int(h*.17)))
            overlay.paste(image,(int(w*.04),int(h*.81)),image)
    words=cta.split(); lines=[]; line=''
    for word in words:
        test=(line+' '+word).strip()
        if draw.textlength(test,font=font)>w*.68 and line:
            lines.append(line);line=word
        else: line=test
    if line: lines.append(line)
    if len(lines)>3:
        raise MediaError('End-card copy is too long. Use a shorter call to action.')
    for i,line in enumerate(lines):
        draw.text((int(w*.28),int(h*.83)+i*int(w*.05)),line,font=font,fill='white')
    png=dst.parent/'brand.png';overlay.save(png)
    ffmpeg(['-i',src,'-i',png,'-filter_complex',f"[0:v][1:v]overlay=enable='gte(t,{max(0,info['duration']-seconds):.4f})'[v]",
        '-map','[v]','-map','0:a:0','-c:v','libx264','-preset','fast','-crf','18','-c:a','copy','-movflags','+faststart',dst])
